        let twist_class = inner(&datum, twist, 6);
        let decomposition =
            CayleyCrossDecomposition::build(&twist_class, &tw(&twist_class, identity_action), 8)
                .unwrap();
        assert!(decomposition.cayley_roots().is_empty());
        assert!(decomposition.cross_word().is_empty());
    }

